import{_t as e,it as t,n,rt as r}from"./chunks/framework.C1oW5ckO.js";var i=JSON.parse(`{"title":"Pumpkin Plugin API","description":"","frontmatter":{"editLink":"https://github.com/filiphsps/pumpkin-plugins/edit/master/GLOSSARY.md"},"headers":[],"relativePath":"GLOSSARY.md","filePath":"GLOSSARY.md","lastUpdated":1792084193000}`),a={name:`GLOSSARY.md`};function o(n,i,a,o,s,c){return e(),r(`div`,null,[...i[0]||=[t(`<h1 id="pumpkin-plugin-api" tabindex="-1">Pumpkin Plugin API <a class="header-anchor" href="#pumpkin-plugin-api" aria-label="Permalink to “Pumpkin Plugin API”">​</a></h1><p>Terms for the host contract that Pumpkin plugins compile against.</p><h2 id="language" tabindex="-1">Language <a class="header-anchor" href="#language" aria-label="Permalink to “Language”">​</a></h2><p><strong>WIT package version</strong>: The version string declared by a WIT package, such as <code>0.1.0</code>. It does not uniquely identify an API target when release and nightly contracts share that string.</p><p><strong>API target</strong>: A distinct Pumpkin host API contract that a plugin is built against. Multiple API targets may share the same WIT package version.</p><p><strong>API package version</strong>: The release version of the TypeScript facade package. It identifies the API library release, not the host ABI or API target. <em>Avoid</em>: WIT package version</p><p><strong>Plugin registration</strong>: The association between a plugin and the host that identifies which plugin supplies metadata and receives lifecycle and inter-plugin message callbacks. It persists across the plugin&#39;s load and unload cycles. <em>Avoid</em>: Callback registration</p><p><strong>Callback registration</strong>: The association between a plugin callback and a host operation, such as an event, command, or scheduled task. It belongs to one plugin load and must be recreated after a later load. <em>Avoid</em>: Plugin registration</p><p><strong>WASI capability</strong>: A plugin&#39;s declared need for one or more WASI-provided services, such as HTTP or filesystem access. It describes the plugin&#39;s host-service requirements; a Pumpkin permission is a separate authorization. <em>Avoid</em>: WASI permission, Pumpkin permission</p><p><strong>Pumpkin permission</strong>: A host authorization that controls whether a plugin may perform a protected operation or access a protected resource through Pumpkin. The server operator grants it to the plugin. <em>Avoid</em>: WASI capability</p>`,10)]])}var s=n(a,[[`render`,o]]);export{i as __pageData,s as default};